/**
 * Billing report formatter. Renders records into the line format used by the
 * finance export.
 */
export function formatReport(records) {
  const lines = ['id|name|amount|discount|created']
  for (const record of records) {
    const amount = (record.amount ?? 0).toFixed(2)
    const discount = (record.discount ?? 0).toFixed(2)
    const created = new Date(record.createdAt ?? 0).toISOString()
    lines.push(`${record.id}|${record.name}|${amount}|${discount}|${created}`)
  }
  return lines
}

args.new_string:
/**
 * Billing report formatter. Renders records into the line format used by the
 * finance export.
 *
 * Field units and semantics follow docs/API.md as amended by the newest entry
 * in docs/CHANGELOG.md:
 * - `amount` is in cents: rendered as amount / 100 with two decimals.
 * - `discount` is the discounted amount in cents: rendered as-is with two
 *   decimals (never computed from a rate).
 * - `created` is rendered from the UTC epoch-millisecond `createdAt` in the
 *   +08:00 timezone, as an ISO-8601 string with an explicit `+08:00` offset.
 */

const UTC_PLUS_8_MS = 8 * 60 * 60 * 1000

function formatCreated(createdAt) {
  // Shift the instant by +8h and render in UTC: the UTC fields of the shifted
  // instant equal the wall-clock time in the +08:00 timezone.
  return new Date(createdAt + UTC_PLUS_8_MS).toISOString().replace('Z', '+08:00')
}

export function formatReport(records) {
  const lines = ['id|name|amount|discount|created']
  for (const record of records) {
    const amount = ((record.amount ?? 0) / 100).toFixed(2)
    const discount = (record.discount ?? 0).toFixed(2)
    const created = formatCreated(record.createdAt ?? 0)
    lines.push(`${record.id}|${record.name}|${amount}|${discount}|${created}`)
  }
  return lines
}
